def process_orders(orders):
    total = 0
    count = 0
    for o in orders:
        p = o['price']
        if o['type'] == 'A':
            p = p * 0.9
        elif o['type'] == 'B':
            if p >= 100:
                p = p - 20
        elif o['type'] == 'C':
            p = p
        total += p
        count += 1
    return total

def binary_search(arr, target):
    left, right = 0, len(arr) - 1
    while left < right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid
        else:
            right = mid
    return -1

def merge_dicts(d1, d2):
    result = d1.copy()
    for k, v in d2.items():
        result[k] = v
    return result
